---刷新按钮状态
function JapaneseStoryMainDialog:RefreshBtnState()
    local entranceConf = JapaneseStoryMgr:GetEntranceConf()
    for i, v in ipairs(entranceConf) do
        if checkInt(v.type) == JapaneseStoryConstants.EntryBtnType.PLOT then
            -- 主线
            local isUnlock = JapaneseStoryMgr:CheckEntryBtnUnlock(JapaneseStoryConstants.EntryBtnType.PLOT)
            CfUtils.FillText(self.BtnMapLockTitle, v.name)
            CfUtils.FillText(self.BtnMapUnLockTitle, v.name)
            CfUtils.SetActive(self.BtnMapLock, not isUnlock)
            CfUtils.SetActive(self.BtnMapUnLock, isUnlock)
        elseif checkInt(v.type) == JapaneseStoryConstants.EntryBtnType.CARD then
            -- 战牌
            local isUnlock = JapaneseStoryMgr:CheckEntryBtnUnlock(JapaneseStoryConstants.EntryBtnType.CARD)
            CfUtils.FillText(self.BtnCardLockTitle, v.name)
            CfUtils.FillText(self.BtnCardUnLockTitle, v.name)
            CfUtils.SetActive(self.BtnCardLock, not isUnlock)
            CfUtils.SetActive(self.BtnCardUnLock, isUnlock)
        elseif checkInt(v.type) == JapaneseStoryConstants.EntryBtnType.BOSS then
            -- BOSS
            local isUnlock = JapaneseStoryMgr:CheckEntryBtnUnlock(JapaneseStoryConstants.EntryBtnType.BOSS)
            CfUtils.FillText(self.BtnFightLockTitle, v.name)
            CfUtils.FillText(self.BtnFightUnLockTitle, v.name)
            CfUtils.SetActive(self.BtnFightLock, not isUnlock)
            CfUtils.SetActive(self.BtnFightUnLock, isUnlock)
        elseif checkInt(v.type) == JapaneseStoryConstants.EntryBtnType.STORE then
            -- 商店 
            CfUtils.FillText(self.BtnShopText, v.name)
        elseif checkInt(v.type) == JapaneseStoryConstants.EntryBtnType.TASK then
            -- 任务
            CfUtils.FillText(self.BtnTaskText, v.name)
        end
    end
end

