---刷新角色状态
function JapaneseStoryMainDialog:RefreshRoleStatus()
    if self._parameters.random then
        self:RandomRoleStatus()
    end
    self:RefreshRoleNode()
    self:ShowGreetingDialogue()
end

---随机角色状态
function JapaneseStoryMainDialog:RandomRoleStatus()
    local statusVo = JapaneseStoryMgr:GetRoleStatusVo()
    local statusConf = statusVo[math.random(1, #statusVo)]

    local roleNodeConf = {}
    for _, v in ipairs(statusConf.nodeIds) do
        local nodeVo = JapaneseStoryMgr:GetRoleNodeVoById(v)
        if nodeVo then
            table.insert(roleNodeConf, nodeVo)
        end
    end
    JapaneseStoryMgr:SetRoleNodeConf(roleNodeConf)

    local clickLinesConf = {}
    for i, v in ipairs(statusConf.touchLineIds) do
        local tmp = {}
        for _, id in ipairs(v) do
            local vo = JapaneseStoryMgr:GetRoleLineVoById(id)
            if vo then
                table.insert(tmp, vo)
            end
        end
        clickLinesConf[roleNodeConf[i].id] = tmp
    end
    JapaneseStoryMgr:SetClickLinesConf(clickLinesConf)

    local greetingLinesConf = {}
    for _, v in ipairs(statusConf.greetingLineIds) do
        local vo = JapaneseStoryMgr:GetRoleLineVoById(v)
        if vo then
            table.insert(greetingLinesConf, vo)
        end
    end
    JapaneseStoryMgr:SetGreetingLinesConf(greetingLinesConf)

    self._parameters.random = false
    self.controller.Argument.parameters = self._parameters
end

