        --    if isNotNull(spineGo) then
        --        CfUtils.PlaySpine(spineGo, v.action, true)
        --    end
        --end
    end
end

---显示问候对话
function JapaneseStoryMainDialog:ShowGreetingDialogue()
    CfUtils.SetActive(self.DialogueRoot, true)
    local lines = JapaneseStoryMgr:GetGreetingLinesConf()
    local conf = lines[math.random(1, #lines)]
    CfUtils.FillText(self.TextName, conf.name)
    CfUtils.FillText(self.TextDialogue, conf.desc)
    if conf.voicecode then
        CriWareUtils.PlayVoiceById(conf.voicecode)
    end
    -- 重置
    self:SetClickLineId(0)
end

---显示点击对话
function JapaneseStoryMainDialog:ShowClickDialogue(index)
    local nodeVo = JapaneseStoryMgr:GetRoleNodeVo()
    local nodeId = nil
    for _, v in ipairs(nodeVo) do
        if v.node == 'Role' .. index then
            nodeId = v.id
            break
        end
    end
    if not nodeId then return end

    local lines = clone(JapaneseStoryMgr:GetClickLinesConf()[nodeId])
    local id = self:GetClickLineId()
    local conf = nil
    if #lines == 1 then
        conf = lines[1]
    else
        for i, v in ipairs(lines) do
            if checkInt(v.id) == id then
                table.remove(lines, i)
                break
            end
        end
        conf = lines[math.random(1, #lines)]
    end
    if not conf then return end

    CfUtils.FillText(self.TextName, conf.name)
    CfUtils.FillText(self.TextDialogue, conf.desc)
    if conf.voicecode then
        CriWareUtils.PlayVoiceById(conf.voicecode)
    end
    self:SetClickLineId(conf.id)
end

---检查序章
function JapaneseStoryMainDialog:CheckPrologue()
    local activityId = JapaneseStoryMgr:GetActivityId()
    local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerId = playerComp.playerDojo.playerId
    local key = string.format('JapaneseStoryPrologue%s%s', activityId, playerId)
    local value = CfUtils.GetLocalData(key, 0)
    if checkInt(value) > 0 then return end

    CfUtils.WriteLocalData(key, 1)
    local storyId = JapaneseStoryMgr:GetPrologueStoryId()
    JapaneseStoryMgr:PlayingPlot({ storyId })
end

---刷新按钮红点
function JapaneseStoryMainDialog:RefreshBtnRedPoint()
    local shopRedGo = GameUtils.GetRedPointGo(self.BtnShop.gameObject)
    if not JapaneseStoryMgr:IsActive() then
        CfUtils.SetActive(self.BtnMapRedPoint, false)
        CfUtils.SetActive(self.BtnFightRedPoint, false)
        CfUtils.SetActive(self.BtnTaskRedPoint, false)
        CfUtils.SetActive(self.BtnCardRedPoint, false)
        CfUtils.SetActive(self.shopRedGo, false)
        return
    end
    
    -- 任务
    CfUtils.SetActive(self.BtnTaskRedPoint, JapaneseStoryMgr:GetTaskTips() == 0)

    -- 地图
    CfUtils.SetActive(self.BtnMapRedPoint, JapaneseStoryMgr:GetMapRedPointState())
    
    -- 卡牌
    CfUtils.SetActive(self.BtnCardRedPoint, JapaneseStoryMgr:HasCardTips())
    
    CfUtils.SetActive(shopRedGo,JapaneseStoryMgr:GetAchievementTaskTips() == 0)
end
